-- ==============================================================================
-- ATUALIZAÇÃO DA CARTEIRA REAL PREVI-LACERDA (SETEMBRO/2026)
-- Execute este script no SQL Editor do Supabase para sincronizar os 32 ativos oficiais.
-- ==============================================================================

-- 1. Limpa alocações e ativos antigos/fictícios (como Bradesco, Sicoob, BTG, etc.)
DELETE FROM portfolio_allocations;
DELETE FROM assets;

-- 2. Garante o registro da carteira oficial
ON CONFLICT (code) DO UPDATE SET 
    name = EXCLUDED.name, 
    entity_name = EXCLUDED.entity_name;

-- 3. Insere os 32 Ativos Oficiais do Portfólio de Investimentos de Pontes e Lacerda (R$ 138.781.858,93)
ON CONFLICT (cnpj) DO UPDATE SET
    name = EXCLUDED.name,
    trading_name = EXCLUDED.trading_name,
    asset_class = EXCLUDED.asset_class,
    cmn_regulation_id = EXCLUDED.cmn_regulation_id,
    benchmark = EXCLUDED.benchmark,
    risk_level = EXCLUDED.risk_level;

-- 4. Alocações Oficiais da Carteira (R$ 138.781.858,93 - Setembro/2026)
